d":"SIMVAGEN","sfdaTradeName":"SIMVAGEN 20 mg film-coated tablet","ingredients":["Simvastatin"],"strength":"20","dosageForm":"Film-coated tablet","verified":true},{"brand":"SIMCOR","sfdaTradeName":"SIMCOR 20 MG F-C TABLETS","ingredients":["Simvastatin"],"strength":"20","dosageForm":"Film-coated tablet","verified":true},{"brand":"INEGY","sfdaTradeName":"INEGY","ingredients":["Simvastatin","Ezetimibe"],"strength":"20,10","dosageForm":"Tablet","verified":true},{"brand":"KLACID","sfdaTradeName":"KLACID 500MG COATED TAB","ingredients":["Clarithromycin"],"strength":"500","dosageForm":"Coated tablet","verified":true,"aliases":["Klacid XL","Klacid 250mg"]},{"brand":"CLARITT","sfdaTradeName":"CLARITT 500 MG FILM COATED TAB","ingredients":["Clarithromycin"],"strength":"500","dosageForm":"Film-coated tablet","verified":true},{"brand":"KLARIMID","sfdaTradeName":"KLARIMID 500MG F.C. TABLETS","ingredients":["Clarithromycin"],"strength":"500","dosageForm":"Film-coated tablet","verified":true},{"brand":"CLARIXIN","sfdaTradeName":"CLARIXIN 500 MG TABLET","ingredients":["Clarithromycin"],"strength":"500","dosageForm":"Film-coated tablet","verified":true},{"brand":"ELTROXIN","sfdaTradeName":"ELTROXIN 0.1MG TAB","ingredients":["Levothyroxine"],"strength":"0.1","dosageForm":"Tablet","verified":true,"aliases":["Eltroxin 0.05mg"]},{"brand":"EUTHYROX","sfdaTradeName":"EUTHYROX","ingredients":["Levothyroxine"],"strength":"0.1","dosageForm":"Tablet","verified":true},{"brand":"PANADOL","sfdaTradeName":"PANADOL 500 mg film-coated tablet","ingredients":["Acetaminophen"],"strength":"500","dosageForm":"Film-coated tablet","verified":true,"ingredientNote":"SFDA lists the scientific name as PARACETAMOL. DDInter indexes the same molecule as Acetaminophen. The mapping table is where that transatlantic naming split is resolved - which is precisely why a mapping layer has to exist rather than passing names straight through."},{"brand":"PANADOL EXTRA","sfdaTradeName":"PANADOL EXTRA TAB","ingredients":["